            B (torch.Tensor): Input matrix of shape (K, N)
        Returns:
            torch.Tensor: Output matrix of shape (M, N)
        """
        assert A.is_cuda and B.is_cuda
        assert A.dtype == torch.float32 and B.dtype == torch.float32
        A = A.contiguous()
        B = B.contiguous()
        M, K = A.shape
        K2, N = B.shape
        assert K == K2
        out = torch.empty((M, N), dtype=torch.float32, device=A.device)
        module = _get_ptx_module()
        block = (16, 16, 1)
        TILE = 32  # each CTA now computes a 32x32 output tile (2x2 register blocking per thread)
        grid = ((N + TILE - 1) // TILE,
                (M + TILE - 1) // TILE,
                1)
        module.launch(
            "tall_skinny_matmul",
            grid=grid,
            block=block,
            arguments=[A, B, out],
            shared_memory=0,
            stream=torch.cuda.current_stream(A.device),
        )
        return out
